	DB *gorm.DB
}

func (s *PayrollService) GetPayrollStub(ctx context.Context, stubID uint) (*models.PayrollRecord, error) {
	var record models.PayrollRecord

	// BOLA: GORM First() locates record solely by primary key 'stubID'
