corrected_code:
package services

import (
	"context"
	"gorm.io/gorm"
	"myapp/auth"
	"myapp/models"
)

type PayrollService struct {
	DB *gorm.DB
}

func (s *PayrollService) GetPayrollStub(ctx context.Context, stubID uint) (*models.PayrollRecord, error) {
	var record models.PayrollRecord
	tenantID := auth.TenantIDFromContext(ctx)

	if err := s.DB.WithContext(ctx).
		Where("tenant_id = ? AND id = ?", tenantID, stubID).
		First(&record).Error; err != nil {
		return nil, err
	}

	return &record, nil
}
